import('./src/ai/testHarness/raphaelAgentEventCases.js')
  .then((m) => {
    const result = m.runRaphaelAgentEventCases();
    console.log(JSON.stringify(result));
    if (!result.ok) process.exit(1);
  })
  .catch((error) => {
    console.error(error);
    process.exit(2);
  });

import('./src/ai/testHarness/dialogueLoopSmokeCases.js')
  .then((m) => {
    const cases = m.runAllDialogueLoopCases();
    const failed = cases.filter((item) => !item.pass);
    const result = {
      ok: failed.length === 0,
      total: cases.length,
      passed: cases.length - failed.length,
      failed: failed.map((item) => ({
        id: item.id,
        checks: item.checks,
        reply: item.reply,
        turns: item.turns
      }))
    };
    console.log(JSON.stringify(result));
    if (!result.ok) process.exit(1);
  })
  .catch((error) => {
    console.error(error);
    process.exit(2);
  });

